import revl_fs_workspace as _ws
try:
    target = _ws.resolve_within(path)    # must #1
    if not _ws.lexists_confined(target):
        # Ok-conditional: an rm on a missing path registers nothing (243).
        return Err({"code": "ENOENT", "message": "no such file",
                    "path": target})
    # must #3: inside root — and the garbage dir is now itself resolved and
    # refused if it is a symlink, so a planted `.revl-fs-garbage` link can
    # no longer park the removed file outside the boundary.
    parked = _ws.fresh_sidecar(_ws.garbage_dir(), "rm")
    _ws.replace_confined(target, parked)
except _ws.FsOpError as e:
    return Err(e.as_error())
return Ok({"path": target, "garbage": parked})

import revl_fs_workspace as _ws
try:
    real_from = _ws.resolve_within(src)  # must #1, BOTH endpoints
    real_to = _ws.resolve_within(dst)
    if not _ws.lexists_confined(real_from):
        return Err({"code": "ENOENT", "message": "no such source",
                    "path": real_from})
    if _ws.lexists_confined(real_to):
        return Err({"code": "EEXIST", "message": "destination exists",
                    "path": real_to})
    _ws.replace_confined(real_from, real_to)
except _ws.FsOpError as e:
    return Err(e.as_error())
return Ok({"from": real_from, "to": real_to})

import revl_fs_workspace as _ws
try:
    target = _ws.resolve_within(path)    # must #1
    if _ws.lexists_confined(target):
        return Err({"code": "EEXIST", "message": "path already exists",
                    "path": target})
    _ws.mkdir_confined(target)
except _ws.FsOpError as e:
    return Err(e.as_error())
return Ok({"path": target})
